"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["25910"],{4248(e){e.exports=JSON.parse('{"id":"V4-042","slug":"helicopter-money","term":"Helicopter Money","also_known_as":[],"difficulty":"Advanced","definition":"Helicopter money is a policy in which a central bank creates money and distributes it directly to the public or finances government spending or transfers, without expecting it to be repaid, to boost spending.","explanation":["The term comes from economist Milton Friedman, who in 1969 imagined money being dropped from a helicopter to illustrate the effects of increasing the money supply. It describes putting new money directly into people\u2019s hands, rather than working through banks and interest rates.","It differs from quantitative easing. In quantitative easing, the central bank buys assets, such as bonds, which it can later sell, so the money creation can in principle be reversed. With helicopter money, the money is given away or used to fund government spending permanently.","For example, a central bank could create money to fund a one-off payment to every citizen, aiming to boost consumer spending during a deep recession.","Supporters argue it could be a powerful tool when interest rates are near zero. Critics warn it could undermine central bank independence, blur the line between monetary and fiscal policy and, if overused, cause high inflation. Some pandemic support payments, financed by government borrowing while central banks bought large amounts of bonds, were compared with helicopter money, although they were not formally described as such."],"note":"","total":1725,"prev":{"slug":"hedging","term":"Hedging"},"next":{"slug":"herding","term":"Herding"}}')}}]);